export function buildBondsSchedule(startISO = null) {
  return buildScheduleFor(BONDS_MODULES, startISO, BONDS_META.cadenceDays);
}

export function bondsProgressSummary(progress = {}) {
  return progressSummaryFor(BONDS_MODULES, progress);
}

export function exportBondsCurriculumMarkdown(startISO = null) {
  return exportCurriculumMarkdownFor({
    meta: BONDS_META,
    modules: buildBondsSchedule(startISO),
    sessionFlow: BONDS_SESSION_FLOW,
  }, startISO);
}

/** Every Scripture reference this course cites, deduped — what the verse gate walks. */
export function bondsRefs() {
  const seen = new Set();
  for (const m of BONDS_MODULES) {
    for (const part of String((m.anchor && m.anchor.ref) || '').split(';')) {
      const ref = part.trim();
      if (ref) seen.add(ref);
    }
  }
  for (const part of String((BONDS_META.wordFirst && BONDS_META.wordFirst.ref) || '').split(';')) {
    const ref = part.trim();
    if (ref) seen.add(ref);
  }
  return [...seen];
}

